/** Currencies: what each is, where it comes from and what it buys. */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    build
 * depends    scripts/game-wiki/render.mjs
 * used by    —
 * ────────────────────────────────────────────────── generated by `pnpm map` ──
 */
import { bullets, heading, sections, table, titleCase } from '../render.mjs'

export function build(context) {
  const { data } = context.sdk
  const flow = name => data.CURRENCY_FLOW_ROWS.find(row => row.name === name)

  /** Fact lists the data keeps per currency, under the heading they belong to. */
  const factGroups = [
    ['Cash', [...data.CASH_WAVE_FLOW_FACTS, ...data.CASH_IMPROVEMENT_FACTS, ...data.CASH_BONUS_ENHANCEMENT_FACTS]],
    ['Coins', [...data.COIN_ACQUISITION_FACTS, ...data.COIN_IMPROVEMENT_FACTS, ...data.COIN_BONUS_ENHANCEMENT_FACTS]],
    ['Gems', [...data.GEM_ACQUISITION_FACTS, ...data.GEM_SPENDING_FACTS]],
    ['Power Stones', data.POWER_STONE_FACTS],
    ['Medals', data.MEDAL_FACTS],
    ['Elite Cells', [...data.ELITE_CELL_TIER_FACTS, ...data.ELITE_CELL_IMPROVEMENT_FACTS]],
    ['Keys', data.KEY_FACTS],
    ['Bits', data.BIT_FACTS],
    ['Tokens', data.TOKEN_FACTS],
    ['Module Currencies', data.MODULE_CURRENCY_FACTS],
  ]

  context.page(
    'Currencies',
    sections(
      bullets(data.CURRENCY_OVERVIEW_FACTS),
      table(
        ['Currency', 'Kept', 'Summary', 'Comes from', 'Spent on'],
        data.CURRENCY_DEFINITIONS.map(currency => [
          currency.name,
          titleCase(currency.persistence),
          currency.summary,
          (flow(currency.name)?.acquisitionSources ?? []).join('; '),
          (flow(currency.name)?.spendUses ?? []).join('; '),
        ]),
      ),
      ...factGroups.map(([title, facts]) => sections(heading(2, title), bullets(facts))),
    ),
    { source: ['CURRENCY_DEFINITIONS', 'CURRENCY_FLOW_ROWS'] },
  )

  context.group('Economy', ['Currencies'])
}
